(()=>{'use strict';
const U='https://gfggmkeucgqkkyvummpu.supabase.co',K='sb_publishable_ptCVbq9h15prKhT0OO5Zmg_LkE3cbK0';
const $=id=>document.getElementById(id), esc=s=>String(s??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}[c])), enc=s=>encodeURIComponent(String(s??''));
async function api(path){const r=await fetch(U+path,{headers:{apikey:K,Authorization:`Bearer ${K}`,Accept:'application/json'}});const t=await r.text();let d=[];try{d=t?JSON.parse(t):[]}catch{}if(!r.ok)throw Error(`HTTP ${r.status}`);return d}
function activate(id){document.querySelectorAll('.view').forEach(v=>v.classList.remove('active'));$(id)?.classList.add('active');document.querySelectorAll('.nav-link').forEach(b=>b.classList.toggle('active',b.dataset.view===id));window.scrollTo({top:0,behavior:'smooth'});try{window.lucide?.createIcons()}catch{}}
function shell(title,kicker,desc=''){return `<div class="public-page premium-page"><button class="back-home" data-home>← Kembali ke Beranda</button><div class="public-head"><span class="eyebrow">${esc(kicker)}</span><h2>${esc(title)}</h2>${desc?`<p>${esc(desc)}</p>`:''}</div><div id="functional-content"></div></div>`}
function card(x){return `<button class="public-list-card" data-pid="${esc(x.id)}"><span class="problem-icon"><i data-lucide="${x.category==='Pendidikan'?'graduation-cap':x.category==='Kesehatan'?'heart-pulse':x.category==='Infrastruktur'?'landmark':x.category==='Lingkungan'?'leaf':x.category==='Ekonomi'?'chart-no-axes-combined':x.category==='Sosial'?'users':'alert-circle'}"></i></span><span><b>${esc(x.title||'Masalah tanpa judul')}</b><small>${esc(x.category||'Masalah')} · ${esc(x.status||'tercatat')} ${x.updated_at?'· '+new Date(x.updated_at).toLocaleDateString('id-ID'):''}</small></span><em>Detail →</em></button>`}
function wire(){document.querySelectorAll('[data-home]').forEach(b=>b.onclick=()=>window.render('home'));document.querySelectorAll('[data-pid]').forEach(b=>b.onclick=()=>renderDetail(b.dataset.pid));try{window.lucide?.createIcons()}catch{}}
async function renderCategory(category){activate('problems');const h=$('problems');h.innerHTML=shell(category,'MASALAH • '+category,`Masalah publik pada bidang ${category}.`);const c=$('functional-content');c.innerHTML='<div class="public-loading">Memuat masalah…</div>';try{const rows=await api(`/rest/v1/problems?select=id,title,category,status,updated_at,region_id&category=eq.${enc(category)}&order=updated_at.desc&limit=100`);c.innerHTML=rows.length?`<div class="problem-list full-list">${rows.map(card).join('')}</div>`:`<div class="public-empty">Belum ada masalah publik pada bidang ${esc(category)}.</div>`;wire()}catch{c.innerHTML='<div class="public-empty">Data masalah belum dapat dimuat. Silakan coba lagi.</div>';wire()}}
async function renderAllProblems(){activate('problems');const h=$('problems');h.innerHTML=shell('Masalah Publik','MASALAH','Daftar masalah yang tercatat secara publik. Pilih satu untuk melihat detail.');const c=$('functional-content');c.innerHTML='<div class="public-loading">Memuat masalah…</div>';try{const rows=await api('/rest/v1/problems?select=id,title,category,status,updated_at,region_id&order=updated_at.desc&limit=100');c.innerHTML=rows.length?`<div class="problem-list full-list">${rows.map(card).join('')}</div>`:'<div class="public-empty">Belum ada masalah publik yang tersedia.</div>';wire()}catch{c.innerHTML='<div class="public-empty">Data masalah belum dapat dimuat.</div>';wire()}}
async function renderDetail(id){activate('problems');const h=$('problems');h.innerHTML=shell('Detail Masalah','MASALAH');const c=$('functional-content');c.innerHTML='<div class="public-loading">Memuat detail…</div>';try{const rows=await api(`/rest/v1/problems?select=id,title,category,status,description,region_id,created_at,updated_at&id=eq.${enc(id)}&limit=1`);const x=rows[0];if(!x){c.innerHTML='<div class="public-empty">Masalah tidak ditemukan.</div>';wire();return}let region=null;try{region=(await api(`/rest/v1/regions?select=id,name,level,parent_region_id&source_name=eq.BIG&id=eq.${enc(x.region_id)}&limit=1`))[0]}catch{}c.innerHTML=`<article class="problem-detail-card"><button class="back-link" data-all>← Kembali ke masalah</button><span class="eyebrow">${esc(x.category||'MASALAH')}</span><h2>${esc(x.title)}</h2><div class="detail-meta"><span>Status: ${esc(x.status||'tercatat')}</span><span>Wilayah: ${esc(region?.name||'Belum ditentukan')}</span><span>Diperbarui: ${x.updated_at?new Date(x.updated_at).toLocaleDateString('id-ID'):'-'}</span></div><div class="detail-body">${esc(x.description||'Belum ada uraian publik untuk masalah ini.')}</div><div class="detail-actions"><button class="btn-primary" data-report>Laporkan informasi terkait</button>${region?`<button class="btn-outline" data-region="${esc(region.id)}">Lihat wilayah</button>`:''}</div></article>`;c.querySelector('[data-all]').onclick=renderAllProblems;c.querySelector('[data-report]').onclick=()=>window.render('report',region?.name||'');c.querySelector('[data-region]')?.addEventListener('click',e=>{const id=e.currentTarget.dataset.region;if(typeof window.openRegionById==='function')window.openRegionById(id);else window.render('map')});try{window.lucide?.createIcons()}catch{}}catch{c.innerHTML='<div class="public-empty">Detail masalah belum dapat dimuat.</div>';wire()}}
async function renderSearch(q){activate('result');const h=$('result');h.innerHTML=shell('Hasil Pencarian','PENCARIAN',`Hasil untuk “${q}”`);const c=$('functional-content');c.innerHTML='<div class="public-loading">Mencari…</div>';try{const [p,r]=await Promise.all([api(`/rest/v1/problems?select=id,title,category,status,updated_at,region_id&title=ilike.*${enc(q)}*&limit=50`),api(`/rest/v1/regions?select=id,name,level,parent_region_id&source_name=eq.BIG&name=ilike.*${enc(q)}*&limit=50`)]);c.innerHTML=`<div class="search-results"><section><h3>Masalah (${p.length})</h3>${p.map(card).join('')||'<div class="public-empty">Tidak ada masalah yang cocok.</div>'}</section><section><h3>Wilayah (${r.length})</h3>${r.map(x=>`<button class="public-list-card" data-region="${esc(x.id)}"><span class="problem-icon"><i data-lucide="map-pin"></i></span><span><b>${esc(x.name)}</b><small>${esc(x.level||'Wilayah')}</small></span><em>Buka →</em></button>`).join('')||'<div class="public-empty">Tidak ada wilayah yang cocok.</div>'}</section></div>`;wire();c.querySelectorAll('[data-region]').forEach(b=>b.onclick=()=>typeof window.openRegionById==='function'?window.openRegionById(b.dataset.region):window.render('map'))}catch{c.innerHTML='<div class="public-empty">Pencarian belum dapat diproses.</div>';wire()}}
const old=window.render;window.render=async function(v,x=''){if(v==='problems'&&x)return renderCategory(x);if(v==='problems')return renderAllProblems();if(v==='problem-detail')return renderDetail(x);if(v==='result'&&String(x).trim())return renderSearch(String(x).trim());return typeof old==='function'?old(v,x):undefined};
document.addEventListener('click',e=>{const cat=e.target.closest('#data [data-cat]');if(cat){e.preventDefault();e.stopImmediatePropagation();renderCategory(cat.dataset.cat)}},true);
document.addEventListener('click',e=>{const search=e.target.closest('#headerSearch');if(!search)return;e.preventDefault();const input=$('luxQuestion');if($('home')?.classList.contains('active')&&input){input.focus();input.scrollIntoView({behavior:'smooth',block:'center'});return}window.render('home');setTimeout(()=>{const i=$('luxQuestion');i?.focus();i?.scrollIntoView({behavior:'smooth',block:'center'})},80)},true);
})();